ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Strings

fun camelizeArray(payload) =
  payload map ((item) ->
    if (item is Object)
        item mapObject ((value, key) ->
        if (value is Object)
            {
            (camelize(key replace "_" with "")): parsePayload(value)
            } filterObject ((value, key) -> value != null)
        else if (value is Array)
            {
            (camelize(key replace "_" with "")): camelizeArray(value)
            } filterObject ((value, key) -> value != null)
        else
            {
            (camelize(key replace "_" with "")): value
            } filterObject ((value, key) -> value != null))
    else
        item
)

fun parsePayload(payload) =
  if (payload is Array)
    camelizeArray(payload)
  else
    payload mapObject ((value, key) -> if (value is Object)
        {
          (camelize(key replace "_" with "")): parsePayload(value)
        } filterObject ((value, key) -> value != null)
      else if (value is Array)
        {
          (camelize(key replace "_" with "")): camelizeArray(value)
        } filterObject ((value, key) -> value != null)
      else
        {
          (camelize(key replace "_" with "")): value
        } filterObject ((value, key) -> value != null))
output application/json  
---
{
  "responseHeader": parsePayload(payload.WSResponseHeader) filterObject ((value, key) -> value != null)
}

%dw 2.0
import * from dw::core::Strings

var resultJson = read((vars.decryptedResponse as String default "{}"), "application/json")

fun camelizeArray(payload) =
  payload map ((item) ->
    if (item is Object)
        item mapObject ((value, key) ->
        if (value is Object)
            {
            (camelize(key replace "_" with "")): parsePayload(value)
            } filterObject ((value, key) -> value != null)
        else if (value is Array)
            {
            (camelize(key replace "_" with "")): camelizeArray(value)
            } filterObject ((value, key) -> value != null)
        else
            {
            (camelize(key replace "_" with "")): value
            } filterObject ((value, key) -> value != null))
    else
        item
)

fun parsePayload(payload) =
  if (payload is Array)
    camelizeArray(payload)
  else
    payload mapObject ((value, key) -> if (value is Object)
        {
          (camelize(key replace "_" with "")): parsePayload(value)
        } filterObject ((value, key) -> value != null)
      else if (value is Array)
        {
          (camelize(key replace "_" with "")): camelizeArray(value)
        } filterObject ((value, key) -> value != null)
      else
        {
          (camelize(key replace "_" with "")): value
        } filterObject ((value, key) -> value != null))
output application/json  
---
{
  "responseHeader": parsePayload(payload.WSResponseHeader) filterObject ((value, key) -> value != null),
  "responseBody": parsePayload(resultJson) filterObject ((value, key) -> value != null)
}
